historical_sql:
SELECT ROUND(
    100.0 * SUM(CASE WHEN Diagnosis LIKE 'SLE%' THEN 1 ELSE 0 END) / COUNT(*),
    2
) AS percentage
FROM Examination
WHERE Thrombosis > 0;

SELECT ROUND(
    100.0 * SUM(
        CASE WHEN NOT EXISTS (
            SELECT 1
            FROM atom a
            WHERE a.molecule_id = m.molecule_id
              AND a.element = 'F'
        ) THEN 1 ELSE 0 END
    ) / COUNT(*),
    2
) AS percentage
FROM molecule m
WHERE m.label = '+';

generalized_v1_sql:
SELECT ROUND(
    1.0 * (SELECT COUNT(*) FROM bond WHERE molecule_id = 'TR397') /
    (SELECT COUNT(*) FROM atom WHERE molecule_id = 'TR397'),
    2
) AS average_bonds_per_atom;
